// ─────────────────────────────────────────────────────────────────────────────
// Mock Audit Snapshot (SANDBOX_MODE=true)
// Emits the same snapshot shape as the live path (pipelines, open deals and
// association maps) using fictitious records. Each deal exercises one rule:
// clean, orphan, missing data, stale, invalid stage, partial association,
// new-deal grace, remediated, and exempt.
// ─────────────────────────────────────────────────────────────────────────────
const DAY_MS = 24 * 60 * 60 * 1000;
const HOUR_MS = 60 * 60 * 1000;
const iso = (msAgo) => new Date(Date.now() - msAgo).toISOString();
const dateIn = (days) => new Date(Date.now() + days * DAY_MS).toISOString().slice(0, 10);

const pipelines = [
  {
    id: 'default', label: 'Sales Pipeline',
    stages: [
      { id: 'appointmentscheduled', label: 'Appointment Scheduled', metadata: { isClosed: 'false' } },
      { id: 'qualifiedtobuy', label: 'Qualified To Buy', metadata: { isClosed: 'false' } },
      { id: 'presentationscheduled', label: 'Presentation Scheduled', metadata: { isClosed: 'false' } },
      { id: 'contractsent', label: 'Contract Sent', metadata: { isClosed: 'false' } },
      { id: 'syn-quarantine-001', label: 'RevOps Quarantine', metadata: { isClosed: 'false' } },
      { id: 'closedwon', label: 'Closed Won', metadata: { isClosed: 'true' } },
      { id: 'closedlost', label: 'Closed Lost', metadata: { isClosed: 'true' } },
    ],
  },
  {
    id: 'syn-pipeline-renewals', label: 'Renewals',
    stages: [
      { id: 'syn-renewal-open', label: 'Renewal Open', metadata: { isClosed: 'false' } },
      { id: 'syn-renewal-negotiation', label: 'Negotiation', metadata: { isClosed: 'false' } },
      { id: 'syn-renewal-won', label: 'Renewed', metadata: { isClosed: 'true' } },
      { id: 'syn-renewal-lost', label: 'Churned', metadata: { isClosed: 'true' } },
    ],
  },
];

const deal = (id, p) => ({
  id,
  properties: {
    hs_object_id: id,
    dealname: null, amount: null, closedate: null, dealstage: null, pipeline: 'default', hubspot_owner_id: null,
    createdate: iso(60 * DAY_MS), hs_lastmodifieddate: iso(2 * DAY_MS), notes_last_updated: null, notes_last_contacted: null,
    deal_hygiene_status: null, deal_hygiene_issues: null, deal_hygiene_previous_stage: null, deal_hygiene_exempt: null,
    ...p,
  },
});

const deals = [
  deal('5000000001', { dealname: 'SYN-001 Acme Corp · Platform Expansion', amount: '48000', closedate: dateIn(30), dealstage: 'presentationscheduled', hubspot_owner_id: '81000001', notes_last_updated: iso(3 * DAY_MS) }),
  deal('5000000002', { dealname: 'SYN-002 Brightfield Labs · Pilot', amount: '12000', closedate: dateIn(45), dealstage: 'qualifiedtobuy', hubspot_owner_id: '81000002', notes_last_updated: iso(5 * DAY_MS) }),
  deal('5000000003', { dealname: 'SYN-003 Calder Systems · Renewal', pipeline: 'syn-pipeline-renewals', dealstage: 'syn-renewal-open', hubspot_owner_id: '81000001', notes_last_updated: iso(9 * DAY_MS) }),
  deal('5000000004', { dealname: 'SYN-004 Dunmore Logistics · Upsell', amount: '30000', closedate: dateIn(-21), dealstage: 'contractsent', hubspot_owner_id: '81000002', createdate: iso(200 * DAY_MS), notes_last_updated: iso(120 * DAY_MS) }),
  deal('5000000005', { dealname: 'SYN-005 Elmstead Freight · New Logo', amount: '22000', closedate: dateIn(20), dealstage: 'syn-deleted-stage-77', hubspot_owner_id: '81000001', notes_last_updated: iso(6 * DAY_MS) }),
  deal('5000000006', { dealname: 'SYN-006 Fernhill Analytics · Expansion', amount: '18000', closedate: dateIn(40), dealstage: 'appointmentscheduled', notes_last_updated: iso(4 * DAY_MS) }),
  deal('5000000007', { dealname: 'SYN-007 Granite Peak Retail · Trial', dealstage: 'appointmentscheduled', createdate: iso(10 * HOUR_MS) }),
  deal('5000000008', { dealname: 'SYN-008 Harbor Lane Imports · Partner', amount: '9500', closedate: dateIn(25), dealstage: 'syn-quarantine-001', hubspot_owner_id: '81000002', notes_last_updated: iso(2 * DAY_MS), deal_hygiene_status: 'quarantined', deal_hygiene_issues: 'missing_amount; missing_close_date', deal_hygiene_previous_stage: 'qualifiedtobuy' }),
  deal('5000000009', { dealname: 'SYN-009 Juniper Ridge Foods · Internal Test', dealstage: 'appointmentscheduled', deal_hygiene_exempt: 'true' }),
];

const companyAssoc = {
  5000000001: ['7000000001'], 5000000003: ['7000000003'], 5000000004: ['7000000004'], 5000000005: ['7000000005'],
  5000000006: ['7000000006'], 5000000008: ['7000000008'],
};
const contactAssoc = {
  5000000001: ['9100000001', '9100000002'], 5000000003: ['9100000003'], 5000000004: ['9100000004'], 5000000005: ['9100000005'],
  5000000008: ['9100000008'],
};

return [{ json: { source: 'synthetic-fixtures', pagesFetched: 0, pipelines, deals, companyAssoc, contactAssoc, assocErrors: 0 } }];

// ─────────────────────────────────────────────────────────────────────────────
// Build Deal Search Request
// Resolves the target pipelines and their open stages from live pipeline
// metadata, then builds a CRM Search body with OR'ed filter groups:
//   1. target pipeline AND an open stage              (normal open deals)
//   2. target pipeline AND a stage not in the pipeline (invalid / deleted stage)
//   3. pipeline not in the portal's pipelines          (only when no target list)
// Closed-won and closed-lost deals are never scanned.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const pipelines = (Array.isArray($input.first().json.results) ? $input.first().json.results : []).map((p) => ({
  id: String(p.id),
  label: p.label,
  stages: (p.stages || []).map((s) => ({ id: String(s.id), label: s.label, metadata: { isClosed: String(s.metadata?.isClosed ?? 'false') } })),
}));
if (pipelines.length === 0) throw new Error('No deal pipelines returned by HubSpot. Check token scopes (crm.objects.deals.read).');

const known = new Set(pipelines.map((p) => p.id));
const unknownTargets = cfg.targetPipelineIds.filter((id) => !known.has(id));
if (unknownTargets.length) throw new Error(`TARGET_PIPELINE_IDS contains unknown pipeline IDs: ${unknownTargets.join(', ')}`);

const targets = cfg.targetPipelineIds.length ? pipelines.filter((p) => cfg.targetPipelineIds.includes(p.id)) : pipelines;
const targetIds = targets.map((p) => p.id);
const openStageIds = targets.flatMap((p) => p.stages.filter((s) => s.metadata.isClosed !== 'true').map((s) => s.id));
const allStageIds = pipelines.flatMap((p) => p.stages.map((s) => s.id));

const properties = Array.from(new Set([
  'dealname', 'amount', 'closedate', 'dealstage', 'pipeline', 'hubspot_owner_id', 'createdate', 'hs_lastmodifieddate',
  'notes_last_updated', 'notes_last_contacted',
  'deal_hygiene_status', 'deal_hygiene_issues', 'deal_hygiene_previous_stage', 'deal_hygiene_exempt',
  ...cfg.requiredProperties,
]));

const filterGroups = [
  { filters: [{ propertyName: 'pipeline', operator: 'IN', values: targetIds }, { propertyName: 'dealstage', operator: 'IN', values: openStageIds }] },
  { filters: [{ propertyName: 'pipeline', operator: 'IN', values: targetIds }, { propertyName: 'dealstage', operator: 'NOT_IN', values: allStageIds }] },
];
if (!cfg.targetPipelineIds.length) {
  filterGroups.push({ filters: [{ propertyName: 'pipeline', operator: 'NOT_IN', values: pipelines.map((p) => p.id) }] });
}

return [{
  json: {
    pipelines,
    searchBody: { filterGroups, properties, sorts: [{ propertyName: 'hs_object_id', direction: 'ASCENDING' }], limit: 100 },
  },
}];

// ─────────────────────────────────────────────────────────────────────────────
// Flatten Deal Pages
// Collapses paginated CRM Search responses into one item and de-duplicates
// deals that matched more than one filter group.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const byId = new Map();
let pagesFetched = 0;
let reportedTotal = null;

for (const item of $input.all()) {
  pagesFetched += 1;
  if (typeof item.json.total === 'number') reportedTotal = item.json.total;
  for (const r of Array.isArray(item.json.results) ? item.json.results : []) {
    const id = String(r.id ?? r.properties?.hs_object_id ?? '');
    if (id && !byId.has(id)) byId.set(id, { id, properties: r.properties || {} });
  }
}

const deals = [...byId.values()].slice(0, cfg.maxDealsScanned);
return [{
  json: {
    source: 'hubspot',
    pagesFetched,
    reportedTotal,
    truncated: byId.size > deals.length || (reportedTotal !== null && reportedTotal > 10000),
    deals,
  },
}];

// ─────────────────────────────────────────────────────────────────────────────
// Build Association Batches
// Chunks deal IDs into batches of 100 for the v4 associations batch-read API.
// Both association HTTP nodes read their batch from this node by item index.
// ─────────────────────────────────────────────────────────────────────────────
const ids = $input.first().json.deals.map((d) => d.id);
const SIZE = 100;
const out = [];
for (let i = 0; i < ids.length; i += SIZE) {
  out.push({ json: { batchIndex: out.length, inputs: ids.slice(i, i + SIZE).map((id) => ({ id })) } });
}
return out;

// ─────────────────────────────────────────────────────────────────────────────
// Assemble Audit Snapshot
// Joins pipelines, deals and both association batch-read responses into the
// same snapshot shape the sandbox emits. A deal absent from `results` (HubSpot
// reports it under `errors` with a 207 status) has no associations of that type.
// ─────────────────────────────────────────────────────────────────────────────
const { pipelines } = $('Build Deal Search Request').first().json;
const scan = $('Flatten Deal Pages').first().json;
const companyResponses = $('HubSpot: Read Deal→Company Associations').all();
const contactResponses = $input.all();

let assocErrors = 0;
function toMap(responses) {
  const map = {};
  for (const r of responses) {
    const body = r.json || {};
    if (body.error && !Array.isArray(body.results)) assocErrors += 1;
    for (const row of Array.isArray(body.results) ? body.results : []) {
      const from = String(row.from?.id ?? '');
      if (!from) continue;
      map[from] = (row.to || []).map((t) => String(t.toObjectId ?? t.id)).filter(Boolean);
    }
  }
  return map;
}

return [{
  json: {
    source: scan.source,
    pagesFetched: scan.pagesFetched,
    truncated: scan.truncated,
    pipelines,
    deals: scan.deals,
    companyAssoc: toMap(companyResponses),
    contactAssoc: toMap(contactResponses),
    assocErrors,
  },
}];

// ─────────────────────────────────────────────────────────────────────────────
// Evaluate Sanitization & Orphans
// Applies the hygiene rule set to every open deal, assigns severity, decides
// the action (none | flag | quarantine | clear), resolves the quarantine stage
// per pipeline, and trips a circuit breaker when the result looks like a
// misconfiguration rather than a real hygiene problem.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const snap = $input.first().json;
const DAY_MS = 24 * 60 * 60 * 1000;
const HOUR_MS = 60 * 60 * 1000;
const now = Date.now();
const todayUtc = Date.UTC(new Date().getUTCFullYear(), new Date().getUTCMonth(), new Date().getUTCDate());

const SEV = { low: 1, medium: 2, high: 3, critical: 4 };
const RULE_LABELS = {
  orphan_no_associations: 'No company or contact associated',
  missing_company_association: 'No associated company',
  missing_contact_association: 'No associated contact',
  missing_amount: 'Amount is empty',
  zero_amount: 'Amount is zero',
  missing_close_date: 'Close date is empty',
  close_date_past: 'Close date is in the past on an open deal',
  missing_owner: 'No deal owner',
  unknown_pipeline: 'Pipeline does not exist',
  invalid_stage: 'Stage does not belong to the pipeline',
  stale_no_activity: 'No activity within the stale threshold',
  abandoned: 'No activity for more than twice the stale threshold',
};

// ── Pipeline and quarantine stage resolution ──────────────────────────────
const pipelineMap = new Map(snap.pipelines.map((p) => [p.id, { ...p, stageIds: new Set(p.stages.map((s) => s.id)) }]));
let qStageMap = null;
const rawQ = String(cfg.quarantineStageId || '').trim();
if (rawQ.startsWith('{')) {
  try { qStageMap = JSON.parse(rawQ); } catch (e) { throw new Error('QUARANTINE_STAGE_ID looks like JSON but does not parse.'); }
}
function quarantineStageFor(pipelineId) {
  const p = pipelineMap.get(pipelineId);
  if (!p) return null;
  const candidate = qStageMap ? qStageMap[pipelineId] : rawQ;
  return candidate && p.stageIds.has(String(candidate)) ? String(candidate) : null;
}
const quarantineStageIds = new Set(snap.pipelines.map((p) => quarantineStageFor(p.id)).filter(Boolean));

// ── Helpers ───────────────────────────────────────────────────────────────
const blank = (v) => v === null || v === undefined || String(v).trim() === '';
const toMs = (v) => {
  if (blank(v)) return NaN;
  if (/^\d+$/.test(String(v))) return Number(v);
  return Date.parse(String(v));
};

const stats = {
  source: snap.source, pagesFetched: snap.pagesFetched, truncated: Boolean(snap.truncated), scanned: snap.deals.length,
  exempt: 0, inGrace: 0, clean: 0, flagged: 0, quarantined: 0, newlyQuarantined: 0, remediated: 0, unchanged: 0,
  issuesByRule: {},
};

const results = [];
for (const d of snap.deals) {
  const p = d.properties || {};
  const id = String(d.id);

  if (String(p.deal_hygiene_exempt).toLowerCase() === 'true') { stats.exempt += 1; continue; }
  const createdMs = toMs(p.createdate);
  if (Number.isFinite(createdMs) && now - createdMs < cfg.newDealGraceHours * HOUR_MS) { stats.inGrace += 1; continue; }

  const issues = [];
  const add = (code, severity, detail) => issues.push({ code, severity, label: RULE_LABELS[code] || code, detail: detail || null });

  // Association integrity
  const companies = snap.companyAssoc[id] || [];
  const contacts = snap.contactAssoc[id] || [];
  if (cfg.requireCompanyAssociation && cfg.requireContactAssociation && !companies.length && !contacts.length) {
    add('orphan_no_associations', 'critical');
  } else {
    if (cfg.requireCompanyAssociation && !companies.length) add('missing_company_association', 'high');
    if (cfg.requireContactAssociation && !contacts.length) add('missing_contact_association', 'medium');
  }

  // Required properties
  if (blank(p.amount)) add('missing_amount', 'high');
  else if (Number(p.amount) <= 0 && !cfg.allowZeroAmount) add('zero_amount', 'medium');

  const closeMs = toMs(p.closedate);
  if (!Number.isFinite(closeMs)) add('missing_close_date', 'high');
  else if (closeMs < todayUtc - cfg.closeDateGraceDays * DAY_MS) add('close_date_past', 'medium', new Date(closeMs).toISOString().slice(0, 10));

  if (blank(p.hubspot_owner_id)) add('missing_owner', 'high');

  // Pipeline and stage integrity
  const pipe = pipelineMap.get(String(p.pipeline || ''));
  if (!pipe) add('unknown_pipeline', 'critical', p.pipeline || 'empty');
  else if (!pipe.stageIds.has(String(p.dealstage || ''))) add('invalid_stage', 'critical', p.dealstage || 'empty');

  for (const prop of cfg.requiredProperties) {
    if (blank(p[prop])) issues.push({ code: `missing_${prop}`, severity: 'low', label: `Required property "${prop}" is empty`, detail: null });
  }

  // Abandonment
  const activityMs = Math.max(...[p.notes_last_updated, p.notes_last_contacted].map(toMs).filter(Number.isFinite), -Infinity);
  const referenceMs = Number.isFinite(activityMs) ? activityMs : createdMs;
  const idleDays = Number.isFinite(referenceMs) ? Math.floor((now - referenceMs) / DAY_MS) : null;
  if (idleDays !== null && idleDays > cfg.staleDays * 2) add('abandoned', 'high', `${idleDays} days idle`);
  else if (idleDays !== null && idleDays > cfg.staleDays) add('stale_no_activity', 'medium', `${idleDays} days idle`);

  // ── Decision ────────────────────────────────────────────────────────────
  const maxSeverity = issues.reduce((m, i) => (SEV[i.severity] > SEV[m] ? i.severity : m), 'low');
  const previousStatus = String(p.deal_hygiene_status || '').toLowerCase() || null;
  const qStage = pipe ? quarantineStageFor(pipe.id) : null;
  const inQuarantineStage = quarantineStageIds.has(String(p.dealstage));

  let action = 'none';
  let status = 'clean';
  if (issues.length === 0) {
    if (previousStatus === 'flagged' || previousStatus === 'quarantined') action = 'clear';
  } else if (SEV[maxSeverity] >= SEV[cfg.quarantineMinSeverity]) {
    action = 'quarantine';
    status = 'quarantined';
  } else {
    action = 'flag';
    status = 'flagged';
  }

  const stageMove = action === 'quarantine' && cfg.quarantineMode === 'stage' && qStage && !inQuarantineStage
    ? { from: String(p.dealstage), to: qStage } : null;
  const prevStage = String(p.deal_hygiene_previous_stage || '');
  const stageRestore = action === 'clear' && inQuarantineStage && cfg.autoRestoreRemediated && pipe && pipe.stageIds.has(prevStage) && !quarantineStageIds.has(prevStage)
    ? { from: String(p.dealstage), to: prevStage } : null;

  const issueCodes = issues.map((i) => i.code).join('; ');
  const changed = action === 'clear' || stageMove !== null || (action !== 'none' && (status !== previousStatus || issueCodes !== String(p.deal_hygiene_issues || '')));
  const newlyQuarantined = action === 'quarantine' && previousStatus !== 'quarantined';

  for (const i of issues) stats.issuesByRule[i.code] = (stats.issuesByRule[i.code] || 0) + 1;
  if (action === 'none') stats.clean += 1;
  if (action === 'flag') stats.flagged += 1;
  if (action === 'quarantine') stats.quarantined += 1;
  if (newlyQuarantined) stats.newlyQuarantined += 1;
  if (action === 'clear') stats.remediated += 1;
  if (!changed && action !== 'none') stats.unchanged += 1;

  results.push({
    id,
    dealname: String(p.dealname || `Deal ${id}`).slice(0, 200),
    pipelineId: pipe ? pipe.id : String(p.pipeline || ''),
    pipelineLabel: pipe ? pipe.label : 'Unknown pipeline',
    stageId: String(p.dealstage || ''),
    stageLabel: pipe ? (pipe.stages.find((s) => s.id === String(p.dealstage))?.label || 'Invalid stage') : 'Unknown',
    ownerId: blank(p.hubspot_owner_id) ? null : String(p.hubspot_owner_id),
    amount: blank(p.amount) ? null : Number(p.amount),
    idleDays,
    associations: { companies: companies.length, contacts: contacts.length },
    issues,
    maxSeverity: issues.length ? maxSeverity : null,
    previousStatus,
    status,
    action,
    changed,
    newlyQuarantined,
    stageMove,
    stageRestore,
    quarantineStageAvailable: Boolean(qStage),
  });
}

// ── Circuit breaker ───────────────────────────────────────────────────────
const evaluated = results.length;
const nonCompliant = results.filter((r) => r.issues.length > 0).length;
const nonCompliantPct = evaluated ? Math.round((nonCompliant / evaluated) * 1000) / 10 : 0;
const reasons = [];
if (stats.newlyQuarantined > cfg.maxQuarantinePerRun) reasons.push(`${stats.newlyQuarantined} new quarantines exceed MAX_QUARANTINE_PER_RUN (${cfg.maxQuarantinePerRun})`);
if (evaluated >= 20 && nonCompliantPct > cfg.circuitBreakerPct) reasons.push(`${nonCompliantPct}% of evaluated deals are non-compliant (limit ${cfg.circuitBreakerPct}%)`);
if (snap.assocErrors > 0) reasons.push(`${snap.assocErrors} association batch(es) failed; orphan detection is unreliable`);
if (cfg.quarantineMode === 'stage' && quarantineStageIds.size === 0) reasons.push('QUARANTINE_MODE=stage but no valid QUARANTINE_STAGE_ID resolved in any pipeline');

return [{
  json: {
    stats: { ...stats, evaluated, nonCompliant, nonCompliantPct },
    circuitBreaker: { open: reasons.length > 0, reasons },
    quarantineStages: [...quarantineStageIds],
    results,
  },
}];

// ─────────────────────────────────────────────────────────────────────────────
// Compose Quarantine & Digest Payloads
// Builds batch-sized HubSpot payloads (deal property and stage updates,
// remediation tasks) and one Slack digest. Only deals whose hygiene state
// actually changed are written, so property history stays readable.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const { stats, circuitBreaker, results } = $input.first().json;
const nowIso = new Date().toISOString();
const HOUR_MS = 60 * 60 * 1000;
const BATCH = 100;
const chunk = (arr) => { const out = []; for (let i = 0; i < arr.length; i += BATCH) out.push(arr.slice(i, i + BATCH)); return out; };
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const SEV_EMOJI = { critical: '🛑', high: '🟠', medium: '🟡', low: '⚪' };

const FIX = {
  orphan_no_associations: 'Associate the buying company and at least one contact, or close the deal as lost if it is a duplicate or test record.',
  missing_company_association: 'Associate the buying company.',
  missing_contact_association: 'Associate the primary contact (champion or economic buyer).',
  missing_amount: 'Enter the expected contract value.',
  zero_amount: 'Confirm the value; zero-value deals distort pipeline coverage.',
  missing_close_date: 'Set a realistic expected close date.',
  close_date_past: 'Move the close date forward with a reason, or close the deal.',
  missing_owner: 'Assign a deal owner.',
  unknown_pipeline: 'Move the deal to an active pipeline.',
  invalid_stage: 'Select a valid stage in the deal\'s pipeline.',
  stale_no_activity: 'Log the latest activity or schedule a next step.',
  abandoned: 'Re-engage with a dated next step, or close the deal as lost.',
};
const fixFor = (code) => FIX[code] || (code.startsWith('missing_') ? `Populate "${code.slice(8)}".` : 'Review and correct.');

// ── Deal updates ──────────────────────────────────────────────────────────
const updates = results.filter((r) => r.changed).map((r) => {
  const properties = {
    deal_hygiene_status: r.action === 'clear' ? 'clean' : r.status,
    deal_hygiene_issues: r.action === 'clear' ? '' : r.issues.map((i) => i.code).join('; ').slice(0, 1000),
    deal_hygiene_severity: r.action === 'clear' ? '' : (r.maxSeverity || ''),
    deal_hygiene_last_audit_at: nowIso,
  };
  if (r.action === 'clear') properties.deal_hygiene_flagged_at = '';
  else if (r.previousStatus !== r.status) properties.deal_hygiene_flagged_at = nowIso;
  if (r.stageMove) {
    properties.dealstage = r.stageMove.to;
    properties.deal_hygiene_previous_stage = r.stageMove.from;
  }
  if (r.stageRestore) {
    properties.dealstage = r.stageRestore.to;
    properties.deal_hygiene_previous_stage = '';
  }
  return { id: r.id, properties };
});

// ── Remediation tasks (newly quarantined deals only) ─────────────────────
const tasks = cfg.createRemediationTasks ? results.filter((r) => r.newlyQuarantined).map((r) => {
  const ownerId = r.ownerId || cfg.revopsDefaultOwnerId || null;
  const properties = {
    hs_timestamp: new Date(Date.now() + cfg.taskDueHours * HOUR_MS).toISOString(),
    hs_task_subject: `🧹 Remediate deal: ${r.dealname}`.slice(0, 250),
    hs_task_body: [
      `<p><strong>This deal was quarantined by the RevOps pipeline sanitization guard.</strong></p>`,
      `<p>Pipeline: ${esc(r.pipelineLabel)} · Stage: ${esc(r.stageLabel)} · Highest severity: <strong>${esc(String(r.maxSeverity).toUpperCase())}</strong></p>`,
      `<ul>${r.issues.map((i) => `<li><strong>${esc(i.label)}</strong>${i.detail ? ` (${esc(i.detail)})` : ''}: ${esc(fixFor(i.code))}</li>`).join('')}</ul>`,
      r.stageMove ? `<p>The deal was moved to the quarantine stage. Its previous stage is stored in <em>deal_hygiene_previous_stage</em>.</p>` : '',
      '<p>Once fixed, the next audit clears the quarantine status automatically.</p>',
      `<p><em>n8n-hubspot-orphan-deal-pipeline-sanitization-guard (dhRobin Systems), run ${esc(cfg.runId)}.</em></p>`,
    ].join(''),
    hs_task_status: 'NOT_STARTED',
    hs_task_priority: r.maxSeverity === 'critical' ? 'HIGH' : 'MEDIUM',
    hs_task_type: 'TODO',
  };
  if (ownerId) properties.hubspot_owner_id = String(ownerId);
  return {
    properties,
    associations: [{ to: { id: r.id }, types: [{ associationCategory: 'HUBSPOT_DEFINED', associationTypeId: 216 }] }],
  };
}) : [];

// ── Slack digest ──────────────────────────────────────────────────────────
const clip = (s, n) => (s.length > n ? `${s.slice(0, n - 1)}…` : s);
const link = (id) => (cfg.portalId ? `${cfg.hubspotUiBaseUrl}/contacts/${cfg.portalId}/record/0-3/${id}` : null);
const quarantinedList = results.filter((r) => r.action === 'quarantine')
  .sort((a, b) => ({ critical: 4, high: 3, medium: 2, low: 1 }[b.maxSeverity] - { critical: 4, high: 3, medium: 2, low: 1 }[a.maxSeverity]) || (b.amount || 0) - (a.amount || 0));
const ruleLines = Object.entries(stats.issuesByRule).sort((a, b) => b[1] - a[1]).map(([k, v]) => `• \`${k}\`: ${v}`).join('\n') || '• none';
const modeTags = [cfg.sandboxMode ? 'SANDBOX' : 'LIVE', cfg.dryRun ? 'DRY RUN' : (circuitBreaker.open ? 'WRITES BLOCKED' : 'SYNCED'), `mode: ${cfg.quarantineMode}`].join(' · ');

const dealLines = quarantinedList.slice(0, 10).map((r) => {
  const name = link(r.id) ? `<${link(r.id)}|${r.dealname.replace(/[<>|]/g, '')}>` : r.dealname;
  return `${SEV_EMOJI[r.maxSeverity]} ${name}${r.newlyQuarantined ? ' *(new)*' : ''}: ${r.issues.map((i) => i.code).join(', ')}`;
}).join('\n');

const slackPayload = {
  text: `Pipeline sanitization: ${stats.quarantined} quarantined, ${stats.flagged} flagged, ${stats.remediated} remediated`,
  blocks: [
    { type: 'header', text: { type: 'plain_text', text: '🧹 Deal Pipeline Sanitization Digest' } },
    { type: 'context', elements: [{ type: 'mrkdwn', text: clip(`Scanned *${stats.scanned}* · evaluated *${stats.evaluated}* · ${modeTags}`, 2900) }] },
    ...(circuitBreaker.open ? [{ type: 'section', text: { type: 'mrkdwn', text: clip(`:rotating_light: *Circuit breaker open: no CRM changes were made.*\n${circuitBreaker.reasons.map((r) => `• ${r}`).join('\n')}`, 2900) } }] : []),
    { type: 'section', fields: [
      { type: 'mrkdwn', text: `*Quarantined*\n${stats.quarantined} (${stats.newlyQuarantined} new)` },
      { type: 'mrkdwn', text: `*Flagged*\n${stats.flagged}` },
      { type: 'mrkdwn', text: `*Remediated*\n${stats.remediated}` },
      { type: 'mrkdwn', text: `*Clean*\n${stats.clean}` },
      { type: 'mrkdwn', text: `*Non-compliant*\n${stats.nonCompliantPct}%` },
      { type: 'mrkdwn', text: `*Exempt / grace*\n${stats.exempt} / ${stats.inGrace}` },
    ] },
    { type: 'section', text: { type: 'mrkdwn', text: clip(`*Issues by rule*\n${ruleLines}`, 2900) } },
    ...(dealLines ? [{ type: 'section', text: { type: 'mrkdwn', text: clip(`*Quarantine queue (top ${Math.min(10, quarantinedList.length)})*\n${dealLines}`, 2900) } }] : []),
    ...(quarantinedList.length > 10 ? [{ type: 'context', elements: [{ type: 'mrkdwn', text: `+${quarantinedList.length - 10} more in the HubSpot view *RevOps Quarantine* (deal_hygiene_status = quarantined).` }] }] : []),
    { type: 'context', elements: [{ type: 'mrkdwn', text: `n8n-hubspot-orphan-deal-pipeline-sanitization-guard · dhRobin Systems · run ${cfg.runId}` }] },
  ],
};

const writesAllowed = !circuitBreaker.open;
return [{
  json: {
    dryRun: cfg.dryRun,
    syncToHubspot: cfg.syncToHubspot && writesAllowed,
    notifySlack: cfg.notifySlack,
    circuitBreaker,
    counts: { updates: updates.length, tasks: tasks.length, quarantined: stats.quarantined, flagged: stats.flagged, remediated: stats.remediated, digestWorthy: stats.quarantined + stats.flagged + stats.remediated + (circuitBreaker.open ? 1 : 0) },
    stats,
    updateBatches: chunk(updates),
    taskBatches: chunk(tasks),
    slackPayload,
    results: results.map((r) => ({ id: r.id, dealname: r.dealname, action: r.action, status: r.status, maxSeverity: r.maxSeverity, issues: r.issues.map((i) => i.code), changed: r.changed, newlyQuarantined: r.newlyQuarantined, stageMove: r.stageMove, stageRestore: r.stageRestore })),
  },
}];

// Collapse batch-update responses into one item so downstream steps run once.
const responses = $input.all().map((i) => i.json);
const updated = responses.reduce((n, r) => n + (Array.isArray(r.results) ? r.results.length : 0), 0);
const errors = responses.reduce((n, r) => n + (Array.isArray(r.errors) ? r.errors.length : 0), 0);
return [{ json: { batches: responses.length, updated, errors } }];
